package org.sleepwell.app;

import android.app.*;import android.content.*;import android.os.*;import android.graphics.Rect;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.TextView;import androidx.activity.ComponentActivity;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import org.junit.Test;import java.io.File;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;

/** Private configuration and actual generated decoder proof only. No CameraX/AlarmActivity output. */
public final class BarcodeCodeFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);volatile Activity current;
    static final class Access implements QrCameraAccess.Port {volatile QrCameraAccess.Status state=QrCameraAccess.Status.NEEDED;volatile int requests;public QrCameraAccess.Status status(Activity a){return state;}public void request(Activity a){requests++;}}
    static final class Camera implements QrCamera.Port {final View preview;volatile String format=MorningBarcode.QR;volatile QrScanSession.Listener listener;Camera(ComponentActivity a){preview=new View(a);}public void format(String format){this.format=format;}public View preview(){return preview;}public void start(QrScanSession.Listener listener){this.listener=listener;}public void close(){}}
    interface Check {boolean ready()throws Exception;}
    void await(String operation,Check check)throws Exception{long deadline=SystemClock.elapsedRealtime()+12000;while(!check.ready()){if(SystemClock.elapsedRealtime()>deadline)throw new AssertionError("Barcode fixture did not reach "+operation);Thread.sleep(30);}}
    View root(){for(View view:WindowInspector.getGlobalWindowViews())if(view.hasWindowFocus()&&view.isAttachedToWindow()&&view.getContext().getPackageName().equals(c.getPackageName()))return view;return null;}
    View find(View view,String label){if(view==null)return null;if(label.contentEquals(view.getContentDescription()==null?"":view.getContentDescription())||view instanceof TextView&&label.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++){View found=find(group.getChildAt(n),label);if(found!=null)return found;}}return null;}
    Rect target(String label,boolean clickable){Rect[] result={null};i.runOnMainSync(()->{View view=find(root(),label);if(clickable)while(view!=null&&!view.isClickable())view=view.getParent() instanceof View?(View)view.getParent():null;if(view==null||!view.isEnabled())return;Rect visible=new Rect();if(!view.getGlobalVisibleRect(visible)||visible.width()!=view.getWidth()||visible.height()!=view.getHeight()){view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),false);return;}if(clickable&&(visible.height()<Design.dp(c,48)||visible.width()<Design.dp(c,48)))return;int[] screen=new int[2];view.getLocationOnScreen(screen);result[0]=new Rect(screen[0],screen[1],screen[0]+view.getWidth(),screen[1]+view.getHeight());});return result[0];}
    void frame()throws Exception{CountDownLatch commit=new CountDownLatch(1);i.runOnMainSync(()->{View owner=root();assertNotNull("Focused app window",owner);owner.getViewTreeObserver().registerFrameCommitCallback(commit::countDown);owner.invalidate();});assertTrue("Committed app frame",commit.await(5,TimeUnit.SECONDS));}
    UiObject2 object(String description)throws Exception{await("visible "+description,()->target(description,false)!=null);frame();UiObject2 view=d.wait(Until.findObject(By.desc(description)),5000);assertNotNull(description,view);return view;}
    void click(String label)throws Exception{await("clickable "+label,()->target(label,true)!=null);frame();Rect bounds=target(label,true);assertNotNull(label,bounds);assertTrue(d.click(bounds.centerX(),bounds.centerY()));}
    boolean ime(){boolean[] visible={false};i.runOnMainSync(()->{View owner=root();WindowInsets insets=owner==null?null:owner.getRootWindowInsets();visible[0]=insets!=null&&insets.isVisible(WindowInsets.Type.ime());});return visible[0];}
    void finishInput()throws Exception{if(ime()){assertTrue(d.pressBack());await("closed keyboard",()->!ime());}}
    void shown(String text){assertTrue(text,d.wait(Until.hasObject(By.text(text)),6000));}
    void recreate(String text)throws Exception{Activity before=current;Instrumentation.ActivityMonitor monitor=i.addMonitor(current.getClass().getName(),null,false);try{i.runOnMainSync(current::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}await("recreated focused activity",()->current!=before&&current.hasWindowFocus());shown(text);}
    void capture(String name)throws Exception{i.waitForIdleSync();frame();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(d.takeScreenshot(new File(folder,"barcode-code-"+name+".png")));}
    String digest()throws Exception{BitMatrix matrix=new MultiFormatWriter().encode("MORNING-42",BarcodeFormat.CODE_128,640,240,Map.of(EncodeHintType.MARGIN,20));byte[] luma=new byte[matrix.getWidth()*matrix.getHeight()];for(int y=0;y<matrix.getHeight();y++)for(int x=0;x<matrix.getWidth();x++)luma[y*matrix.getWidth()+x]=(byte)(matrix.get(x,y)?0:255);return new QrDecoder("CODE_128").digest(luma,matrix.getWidth(),matrix.getHeight());}
    @Test public void explicitBarcodeModePermissionCancelCaptureRecreationAndReopenRemainPrivate()throws Exception{String name="barcode-flow-"+UUID.randomUUID();Records.Factory oldRecords=Records.factory;AlarmScheduling.Port oldScheduling=AlarmScheduling.port;QrCameraAccess.Port oldAccess=QrCameraAccess.port;QrCamera.Factory oldCamera=QrCamera.factory;Map<String,?> original=new HashMap<>(Prefs.of(c).getAll());Access access=new Access();List<Camera> cameras=new CopyOnWriteArrayList<>();List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue(a instanceof AlarmEditorActivity||a instanceof QrCodeActivity);assertFalse(a.getIntent().getBooleanExtra("challenge",false));owned.add(a);}public void onActivityResumed(Activity a){current=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        try{Records.factory=context->new Store(context,name);AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context x){return true;}public void schedule(Context x,Alarm alarm){assertFalse(alarm.enabled);}};QrCameraAccess.port=access;QrCamera.factory=a->{Camera camera=new Camera(a);cameras.add(camera);return camera;};Alarm alarm=new Alarm(1);alarm.enabled=false;try(Store store=new Store(c,name)){store.save(alarm);}Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}shown("Edit alarm");click("Challenges");click("Configure QR code");shown("Add a morning code");click("Barcode");shown("EAN-13");capture("mode");click("Barcode format");click("Code 128");object("Barcode location name").setText("Kitchen");finishInput();click("Allow camera");await("exactly one permission request callback",()->access.requests==1);assertEquals(1,access.requests);i.runOnMainSync(()->((QrCodeActivity)current).onRequestPermissionsResult(QrCameraAccess.REQUEST,new String[]{android.Manifest.permission.CAMERA},new int[]{android.content.pm.PackageManager.PERMISSION_DENIED}));assertTrue(object("QR scan error").getText().contains("not allowed"));assertTrue(cameras.isEmpty());click("Back");shown("Challenges");try(Store store=new Store(c,name)){assertFalse(store.alarm(1).json().has("routine"));}
        click("Configure QR code");shown("Add a morning code");click("Barcode");click("Barcode format");click("Code 128");object("Barcode location name").setText("Kitchen");finishInput();access.state=QrCameraAccess.Status.READY;recreate("Add a morning code");shown("Code 128");click("Scan code");await("started first selected camera",()->!cameras.isEmpty()&&cameras.get(cameras.size()-1).listener!=null);assertTrue(d.wait(Until.hasObject(By.desc("Barcode camera preview")),5000));assertFalse(cameras.isEmpty());Camera first=cameras.get(cameras.size()-1);assertEquals("CODE_128",first.format);String hash=digest();assertNotNull(hash);i.runOnMainSync(()->first.listener.captured(hash));shown("Code captured");capture("captured");click("QR code");await("selected QR mode and cleared capture",()->{boolean[] selected={false};i.runOnMainSync(()->{View mode=find(root(),"QR code");selected[0]=mode!=null&&mode.isSelected();});return selected[0]&&!d.hasObject(By.text("Code captured"));});assertFalse(d.hasObject(By.text("Code captured")));click("Save code");assertFalse(object("QR scan error").getText().isBlank());click("Barcode");click("Barcode format");click("Code 128");int priorCameras=cameras.size();click("Scan code");await("started replacement selected camera",()->cameras.size()==priorCameras+1&&cameras.get(cameras.size()-1).listener!=null);Camera second=cameras.get(cameras.size()-1);assertNotSame(first,second);i.runOnMainSync(()->first.listener.captured(hash));assertFalse(d.hasObject(By.text("Code captured")));i.runOnMainSync(()->second.listener.captured(hash));shown("Code captured");recreate("Add a morning code");shown("Code 128");assertEquals("Kitchen",object("Barcode location name").getText());capture("recreated");click("Save code");shown("Challenges");capture("routine");click("Save routine");Activity editor=current;click("Save alarm");await("persisted editor finished",editor::isDestroyed);try(Store store=new Store(c,name)){MorningCode saved=store.alarm(1).challenges().tasks.get(1).code;assertEquals("CODE_128",saved.format);assertEquals(hash,saved.hash);assertEquals("Kitchen",saved.label);Backup.validate(store.backup());assertFalse(store.backup().toString().contains("MORNING-42"));}
        // Reopen the real task editor from saved state without enabling or scheduling an alarm.
        Alarm saved;try(Store store=new Store(c,name)){saved=store.alarm(1);}monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",saved.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}shown("Edit alarm");click("Challenges");click("Edit task 2 QR code");shown("Add a morning code");shown("Code 128");shown("Code captured");access.state=QrCameraAccess.Status.UNSUPPORTED;recreate("Add a morning code");shown("No supported camera is available.");capture("reopened");assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertEquals(original,Prefs.of(c).getAll());
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());d.takeScreenshot(new File(folder,"barcode-code-failure.png"));d.dumpWindowHierarchy(new File(folder,"barcode-code-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(25);assertTrue(owned.stream().allMatch(Activity::isDestroyed));app.unregisterActivityLifecycleCallbacks(lifecycle);Records.factory=oldRecords;AlarmScheduling.port=oldScheduling;QrCameraAccess.port=oldAccess;QrCamera.factory=oldCamera;c.deleteDatabase(name);}}
}
